  return [{ json: {
    success: false,
    accepted: false,
    status: state.status || 'blocked_missing_inputs',
    missing_inputs: state.missing_inputs || [],
    message: state.message || 'Required inputs are missing. The production run was not started.',
    next_question: state.next_question || 'Please provide the missing required inputs.'
  } }];
}
return [{ json: {
