const input = items[0]?.json || {};
const body = input.body || input;
const now = new Date().toISOString();
const clean = (value) => String(value || '').trim();
const companyName = clean(body.company_name || body.companyName || body.company);
const ticker = clean(body.ticker || body.symbol);
const execType = clean(body.exec_type || body.executive);
const industry = clean(body.industry);
const expertPref = clean(body.expert_pref || body.expert || body.industry_expert);
const serviceProvider = clean(body.service_provider || body.my_company || body.provider_company) || 'MY COMPANY';
const sourceNotes = clean(body.source_notes || body.notes || body.urls);
const peerListRaw = clean(body.peer_list || body.peers || body.known_competitors);
const slideCountRaw = Number(body.slide_count || body.slideCount || 4);
const slideCount = [3, 4, 5].includes(slideCountRaw) ? slideCountRaw : 4;
const missing = [];
if (!companyName) missing.push('company_name');
if (!execType) missing.push('exec_type');
if (!industry) missing.push('industry');
if (!expertPref) missing.push('expert_pref');
if (missing.length) {
  return [{ json: {
    valid: false,
    success: false,
    accepted: false,
    status: 'blocked_missing_inputs',
    missing_inputs: missing,
    message: 'Required inputs are missing. The production run was not started.',
    next_question: missing.includes('company_name')
      ? 'What is the company name you want analyzed and ticker symbol if public?'
      : 'Which C-level executive is this pitch for, what industry is the company in, and which industry expert perspective should I blend with Damodaran?',
    received_at: now
  } }];
}
const expertLibrary = {
  'media': { name: 'Ben Thompson', reason: 'Chosen for media because he is known for aggregation theory, distribution power, and digital business models.' },
  'media & entertainment': { name: 'Ben Thompson', reason: 'Chosen for media and entertainment because he is known for aggregation theory, distribution power, and digital business models.' },
  'gaming': { name: 'Matthew Ball', reason: 'Chosen for gaming because he is known for platform strategy, interactive media, and the economics of digital worlds.' },
  'banking': { name: 'Jamie Dimon', reason: 'Chosen for banking because he is strongly associated with banking strategy, risk, regulation, and capital discipline.' },
  'retail': { name: 'Jeff Bezos', reason: 'Chosen for retail because he is associated with customer obsession, scale economics, and operating discipline.' },
  'manufacturing': { name: 'Taiichi Ohno', reason: 'Chosen for manufacturing because he is associated with lean production, waste reduction, and operating flow.' },
  'healthcare': { name: 'Atul Gawande', reason: 'Chosen for healthcare because he is associated with systems thinking, quality, and operational reliability in healthcare.' },
  'technology': { name: 'Bill Gurley', reason: 'Chosen for technology because he is known for unit economics, marketplace quality, and disciplined growth.' },
  'saas': { name: 'David Skok', reason: 'Chosen for SaaS because he is known for SaaS unit economics, CAC, churn, and scalable growth models.' }
};
const industryKey = industry.toLowerCase();
const picked = expertLibrary[industryKey] || expertLibrary[Object.keys(expertLibrary).find((key) => industryKey.includes(key) || key.includes(industryKey))] || { name: 'Bill Gurley', reason: 'Chosen as a general technology and growth-business expert because the industry did not have a more specific configured match.' };
const expertResolved = expertPref.toLowerCase() === 'pick for me'
  ? picked
  : { name: expertPref, reason: `Founder selected ${expertPref} as the industry expert perspective.` };
const runId = body.run_id || `dfa_prod_${Date.now()}`;
const state = {
  valid: true,
  run_id: runId,
  created_at: now,
  updated_at: now,
  status: 'queued',
  current_stage: 'queued',
  inputs: {
    company_name: companyName,
    ticker,
    exec_type: execType,
    industry,
    company_type: body.company_type || body.companyType || 'auto',
    expert_pref: expertPref,
    expert_resolved: expertResolved,
    service_provider: serviceProvider,
    peer_list: peerListRaw ? peerListRaw.split(',').map((peer) => peer.trim()).filter(Boolean) : [],
    slide_count: slideCount,
    deck_type: `gamma_${slideCount}_slide_production`,
    gamma_api_enabled: Boolean(body.gamma_api_enabled),
    advanced_context: { source_notes: sourceNotes }
  },
  audit_log: [{ timestamp: now, workflow_name: 'DFA - API Start Run', status: 'QUEUED', message: 'Run accepted by production portal after required input validation.' }]
};
return [{ json: state }];
